package com.crm.hr;
import com.crm.hr.entity.EmployeeEvaluation;import com.crm.hr.entity.LeaveEmployeeAssociation;import com.crm.hr.repository.*;import com.crm.hr.service.*;import org.junit.jupiter.api.Test;import org.springframework.data.domain.PageImpl;import org.springframework.security.core.Authentication;import java.util.List;import java.util.Optional;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class PersonalEvaluationServiceTest{
 @Test void personalListUsesAssociatedEmployeeAndFinalizedOnly(){var evaluations=mock(EmployeeEvaluationRepository.class);var associations=mock(EmployeeAssociationService.class);var link=new LeaveEmployeeAssociation();link.setEmployeeId("17");var auth=mock(Authentication.class);when(associations.readOwn(auth)).thenReturn(link);when(evaluations.findAllByEmployeeIdAndStatus(eq("17"),eq(EmployeeEvaluation.Status.FINALIZED),any())).thenReturn(new PageImpl<>(List.of()));var service=new HrWorkflowService(evaluations,mock(JobOfferRepository.class),mock(JobApplicationRepository.class),associations,mock(EmployeeReferenceValidator.class));service.ownFinalizedEvaluations(auth,0,10);verify(evaluations).findAllByEmployeeIdAndStatus(eq("17"),eq(EmployeeEvaluation.Status.FINALIZED),any());verify(associations).readOwn(auth);}
 @Test void personalDetailDoesNotRevealAnotherEmployeeOrDraft(){var evaluations=mock(EmployeeEvaluationRepository.class);var associations=mock(EmployeeAssociationService.class);var link=new LeaveEmployeeAssociation();link.setEmployeeId("17");var auth=mock(Authentication.class);when(associations.readOwn(auth)).thenReturn(link);when(evaluations.findByIdAndEmployeeIdAndStatus(9L,"17",EmployeeEvaluation.Status.FINALIZED)).thenReturn(Optional.empty());var service=new HrWorkflowService(evaluations,mock(JobOfferRepository.class),mock(JobApplicationRepository.class),associations,mock(EmployeeReferenceValidator.class));assertThrows(com.crm.hr.exception.ResourceNotFoundException.class,()->service.ownFinalizedEvaluation(auth,9L));verify(evaluations).findByIdAndEmployeeIdAndStatus(9L,"17",EmployeeEvaluation.Status.FINALIZED);}
}
